/**
 * A **3D Gaussian-Splat volume** — the headline volumetric primitive: a cloud of anisotropic translucent gaussians (position + per-axis scale + orientation + color/opacity), the representation of choice for photoreal capture (video/scan → navigable scene) and volumetric science visualization. Imported from a gaussian PLY (or `.splat`); the DC spherical-harmonic term is baked to an RGB color on import.
 */
export type GaussianSplatFeature = {
  type: "gaussianSplat";
  /** Number of gaussians N. */
  count: number;
  /** Means, 3N (mm). */
  positions: number[];
  /** Per-axis world-space scales, 3N (already exp'd from log-scale on import). */
  scales: number[];
  /** Orientation quaternions, 4N [x,y,z,w] (normalized on import). */
  rotations: number[];
  /**
   * Per-splat RGBA, 4N, 0..1 (SH DC → base color via `0.5 + C0·f_dc`, sigmoid(opacity) → alpha). Kept as the tier-1 view-independent color; higher SH bands (view-dependent) live in `sh`.
   */
  colors: number[];
  /**
   * Spherical-harmonic degree of the ORIGINAL asset (0..3). 0 = DC only (color is exact); 1..3 = the `f_rest_*` coefficients are preserved in `sh` for a view-dependent renderer. We keep the real 3DGS parameter model rather than collapsing to rgba — see the g-splat fidelity note.
   */
  shDegree?: 0 | 3 | 1 | 2;
  /**
   * Higher-band SH coefficients (excluding the DC term already baked into `colors.rgb`). Layout: per splat, `restCount = (shDegree+1)² − 1` coefficients, each an RGB triple, interleaved `[s0_c0_r,s0_c0_g,s0_c0_b, s0_c1_r,…]`. Length = N·restCount·3. Absent for degree-0 assets.
   */
  sh?: number[];
  /** Provenance + roundtrip metadata: the exact source format so export/interop decisions stay sane. */
  source?: {
    format?: string;
    fileId?: string;
    fileName?: string;
    shDegree?: number;
    splatCount?: number;
  };
  id: string;
  name: string;
  suppressed?: boolean;
  /** Populated by rebuild when this feature fails. */
  error?: string;
  /**
   * THE BODY-STATE EDGE — the explicit form of what a timeline used to supply implicitly as "whatever came before".
   */
  consumes?: string[];
  /**
   * DECLARED BY A CODE PART — set only in memory, on a feature a CodeFeature's file declared when the part was opened (`app-3d-design` `model/code-parts.ts`). It holds the code feature as it is stored; a save writes that back in place of every feature it declared, so nothing a file declares is ever written.
   */
  declaredBy?: CodeFeature;
};

/**
 * The record a node holds: the output's locator always, the provenance fields when the run returned them. A run that returned only a file still records where its bytes are, in the same slot.
 */
export type GenNodeRecord = {
  /** The SEMANTIC operator — `inpaint`, not a vendor's endpoint name. */
  operator?: string;
  implementation?: string;
  implementationVersion?: string;
  /** Scheme-prefixed model identity: `replicate:owner/slug:hex`, `fal:owner/slug`. */
  artifactDigest?: string;
  /** Whether that identity genuinely pins the artifact, or names something the vendor can change. */
  artifactImmutable?: boolean;
  /** Digest of the input the model saw, so "the inputs moved" is decidable. */
  inputDigest?: string;
  /** Digest of the authored params, seed included. */
  paramsDigest?: string;
  producedAt?: string;
  output: {
    locator: string;
    digest?: string;
  };
};

/**
 * A GENERATE feature — a creative generative model (`@commandagi/core` `GEN_MODELS`) as a re-runnable node in the feature graph. It projects into the op-graph dock as a `gen:<modelId>` GenNode (see ui/model/opgraph-projection): scalar inputs (prompt/enum/…) ride in `params`, wired image/mesh inputs in `refs` (inputKey → upstream featureId), and running it (the dock's async `runNode`) generates an asset that lands as a separate splat/mesh feature (`addSciFeature`) and bakes its `provenance` record here. The generate feature itself produces no geometry — it's the recipe; the landed feature is the result.
 */
export type GenerateFeature = {
  type: "generate";
  /** The `GEN_MODELS` model id this node runs (e.g. `image-to-splat.trellis`). */
  modelId: string;
  /** Scalar model inputs (prompt/enum/number/seed) — the wireable image/mesh inputs live in `refs`. */
  params: { [key: string]: unknown };
  /** Wired inputs: model input key → upstream feature id (its generated output feeds this model). */
  refs?: { [key: string]: string };
  /**
   * The last run's one record: where its output landed (downstream chaining, and what renders) and, when the run supplied them, the model's identity and the input and param digests.
   */
  provenance?: GenNodeRecord;
  id: string;
  name: string;
  suppressed?: boolean;
  /** Populated by rebuild when this feature fails. */
  error?: string;
  /**
   * THE BODY-STATE EDGE — the explicit form of what a timeline used to supply implicitly as "whatever came before".
   */
  consumes?: string[];
  /**
   * DECLARED BY A CODE PART — set only in memory, on a feature a CodeFeature's file declared when the part was opened (`app-3d-design` `model/code-parts.ts`). It holds the code feature as it is stored; a save writes that back in place of every feature it declared, so nothing a file declares is ever written.
   */
  declaredBy?: CodeFeature;
};

